/** @typedef {{expanded:boolean,troughUpgrade:boolean,shade:boolean,sanitation:boolean,cleanliness:number,soilRemainder:number,standCleanliness:number,canCleanliness:number}} CowBarn */
/** @typedef {{id:string,cowId:string,collectedTick:number,remainingVolumeMl:number,gradeAtMilking:'A'|'B'|'C',freshnessScore:number,storage:'can'|'cooler'}} MilkLot */
