/** @typedef {ReturnType<typeof createCowState>} CowState */
/** Empty additive module. Reading, migration or rendering cannot create a herd. */
export function createCowState(){return {visited:false,starterGrantId:'',balanceVersion:COW.balanceVersion,enteredTick:-1,cows:/** @type {Cow[]} */([]),barn:/** @type {CowBarn|null} */(null),purchaseProof:/** @type {null|{tick:number,feedCapacityG:number,waterCapacityMl:number,availableFeedG:number,availableWaterMl:number}} */(null),feedStoreG:0,feedTrough:{normal:0,starter:0,recovery:0},waterTrough:{normal:0,starter:0,recovery:0},starterRation:{feedG:0,waterMl:0},recoveryRation:{feedG:0,waterMl:0},lots:/** @type {MilkLot[]} */([]),discards:/** @type {Array<{id:number,tick:number,lotId:string,volumeMl:number,reason:'spoiled'|'player'}>} */([]),nextDiscard:1,nextLot:1,nextSale:1,openingMilkMl:0,producedMilkMl:0,soldMilkMl:0,discardedMilkMl:0,milkRevenueRemainder:0,cooler:{owned:false,enabled:false,paidTicks:0,status:/** @type {'off'|'idle'|'cooling'|'paused_no_funds'} */('off')},recovery:{episode:0,active:false,startedTick:-1,lastCompleteTick:-24,nextEligibleTick:0,completed:0},mission:{step:0,inspectedA:false,upgradeViewed:false},grants:/** @type {string[]} */([]),orders:{acceptedId:'',completedIds:/** @type {string[]} */([]),records:/** @type {Array<{id:string,saleId:number,tick:number,volumeMl:number,milkNumerator:number,bonus:number}>} */([])},stats:/** @type {Record<typeof COW_COUNTERS[number],number>} */(Object.fromEntries(COW_COUNTERS.map(k=>[k,0]))),receipts:/** @type {CowReceipt[]} */([]),history:/** @type {CowHistory[]} */([])};}
/** @param {string} id @param {number} tick @param {number} [opening] @returns {Cow} */
export function createCow(id,tick,opening=0){return {id,priorCalving:true,lactationStatus:'lactating',lactationStage:'mid',acquiredTick:tick,nutrition:800,hydration:800,comfort:800,bodyCondition:850,milkReadyMl:opening,producedMilkMl:0,collectedMilkMl:0,totalMilkings:0,productionRemainder:0,feedDemandRemainder:0,lastMilkingTick:-1,milkingDay:Math.floor(tick/24),sessions:0};}
