export function createCowKit(tick){const g=createCowState();g.visited=true;g.starterGrantId='cow.starter.v1';g.enteredTick=tick;g.cows=[createCow('cow.starter.a',tick,COW.openingMilkMl),createCow('cow.starter.b',tick)];g.barn={expanded:false,troughUpgrade:false,shade:false,sanitation:false,cleanliness:75,soilRemainder:0,standCleanliness:55,canCleanliness:90};g.starterRation={feedG:COW.starterFeedG,waterMl:COW.starterWaterMl};g.openingMilkMl=COW.openingMilkMl;g.mission.step=1;return g;}
/** @param {CowState} g */
export const cowCapacity=g=>({cows:g.barn?.expanded?3:2,feedG:COW.feedTroughG,waterMl:g.barn?.troughUpgrade?COW.upgradedWaterTroughMl:COW.waterTroughMl,canMl:COW.canMl,coolerMl:g.cooler.owned?COW.coolerMl:0});
/** @param {{normal:number,starter:number,recovery:number}} supply */
export const cowSupply=supply=>supply.normal+supply.starter+supply.recovery;
/** @param {unknown} value @param {readonly string[]} keys @returns {Record<string,any>} */
function object(value,keys){if(!value||typeof value!=='object'||Array.isArray(value)||Object.getPrototypeOf(value)!==Object.prototype)throw Error('Invalid cow object');const v=/** @type {Record<string,any>} */(value);if(Reflect.ownKeys(v).length!==keys.length||Object.keys(v).length!==keys.length||Object.values(Object.getOwnPropertyDescriptors(v)).some(d=>!Object.hasOwn(d,'value'))||keys.some(k=>!Object.hasOwn(v,k)))throw Error('Unknown or missing cow fields');return v;}
/** @param {unknown} value @param {number} [max] @param {number} [min] */
